	title.add_theme_font_size_override("font_size", 14)
	box.add_child(title)
	if str(plants[id]) != "":
		var seconds := ceili(timer(id))
		var take := small_button("Récolter" if seconds == 0 else "Pousse : %d s" % seconds, func(): harvest(id))
		take.disabled = seconds > 0
		box.add_child(take)
